code.solution:
//go:build debug

package app

import "log"

// Built only when you run `go build -tags=debug`.
// In normal builds this file is dropped, so trace() does not exist —
// any call site must itself be in a debug-tagged file, or behind
// a build-tagged shim with a no-op fallback.
func trace(msg string) {
	log.Printf("[trace] %s", msg)
}

