solution.code:
// file: greeting_default.go
//go:build !fancy

package solution

// Default greeting, used in normal builds.
func Greeting() string { return "hello" }

// ---------------------------------------------------------------
// file: greeting_fancy.go
//go:build fancy

package solution

// Fancy greeting, compiled only with: go build -tags=fancy
func Greeting() string { return "\u2728 hello \u2728" }

// The two files carry mutually-exclusive constraints (!fancy vs fancy),
// so exactly one Greeting() is ever in the build — no duplicate symbol.

codeLab.testHarness:
package solution

import "testing"

// Run with: go test            -> expects "hello"
// Run with: go test -tags fancy -> expects the fancy banner
func TestGreeting(t *testing.T) {
	got := Greeting()
	if got != "hello" && got != "\u2728 hello \u2728" {
		t.Fatalf("unexpected greeting: %q", got)
	}
	// In a default (untagged) build the value must be the plain one.
	if testing.Short() == false && got == "" {
		t.Fatalf("Greeting() returned empty string")
	}
}

